-- =====================================================================
-- استكمال تصحيح مفاتيح الإجابة (2026-10-16) — يُنفَّذ بعد fix-answer-keys-2026-10-16.sql
--   1) الأسئلة التي صحّح مالك المشروع مفتاحها يدويًا: تُنقل ملاحظات البدائل إلى مواضعها الصحيحة
--      (فقط إن بقيت الملاحظات كما وُلدت؛ ما عدّله المالك بنفسه لا يُمس)
--   2) تُعاد نتائج تدريب الطلاب على هذه الأسئلة حسب المفتاح الحالي
--   3) اعتماد الأسئلة المصححة بقرار مالك المشروع (عدا ما يحتاج مراجعة يدوية)
--   4) عرض الأسئلة التي تحتاج مراجعة يدوية كما هي الآن
-- آمن للتكرار.
-- =====================================================================
begin;
create temp table _fx (code text, n int, new_ci int, opts jsonb, notes jsonb, old_notes jsonb) on commit drop;
create temp table _q on commit drop as
  select q.id, q.options = f.opts and a.correct_index = f.new_ci as fixed, f.*
  from _fx f join public.objectives o on o.code = f.code
  join public.questions q on q.objective_id = o.id and q.type = 'mcq' and q.number = f.n
  join public.question_answers a on a.question_id = q.id;

-- 1) الملاحظات
update public.question_answers a set distractor_notes = q.notes from _q q
  where a.question_id = q.id and q.fixed and a.distractor_notes = q.old_notes;
-- 2) نتائج التدريب حسب المفتاح الحالي
update public.practice_answers p set correct = (p.choice = a.correct_index)
  from public.question_answers a join _q q on q.id = a.question_id and q.fixed
  where p.question_id = a.question_id and p.correct is distinct from (p.choice = a.correct_index);
update public.practice_sessions s set score = (select count(*) filter (where pa.correct) from public.practice_answers pa where pa.session_id = s.id)
  where s.finished_at is not null and s.id in (select pa.session_id from public.practice_answers pa join _q q on q.id = pa.question_id and q.fixed);
-- 3) الاعتماد
  select 'question', q.id, 'status', jsonb_build_object('status', qq.status), jsonb_build_object('status', 'approved'),
    'اعتماد السؤال بعد تصحيح مفتاح الإجابة بقرار مالك المشروع (2026-10-16)', 'مالك المشروع'
  from _q q join public.questions qq on qq.id = q.id where q.fixed and qq.status <> 'approved';
update public.questions qq set status = 'approved', reviewed_at = now() from _q q where qq.id = q.id and q.fixed and qq.status <> 'approved';

-- 4) الملخص، ثم الأسئلة التي تحتاج مراجعة يدوية كما هي الآن
select (select count(*) from _q where fixed) as "مصحح ومعتمد",
       (select count(*) from _q where not fixed) as "يحتاج مراجعة يدوية";
select q.code || ' سؤال ' || q.n as "السؤال", qq.stem as "النص", qq.options as "البدائل", a.correct_index + 1 as "رقم الإجابة المحددة",
       a.explanation as "التفسير", qq.status as "الحالة"
  from _q q join public.questions qq on qq.id = q.id join public.question_answers a on a.question_id = q.id
  where not q.fixed order by q.code, q.n;
commit;
